# ============================================================
#  PowerShell 7 profile, generated by the rice (palette: Claude Ember)
#  100% native: PSReadLine only, no modules, no prompt framework.
#  Regenerate with:  node tools/rice.mjs build ember   (then apply)
# ============================================================

# --- History (native PSReadLine) ---
Set-PSReadLineOption -EditMode Windows
Set-PSReadLineOption -HistoryNoDuplicates
Set-PSReadLineOption -MaximumHistoryCount 10000
Set-PSReadLineOption -HistorySearchCursorMovesToEnd
Set-PSReadLineOption -BellStyle None

if (-not [Console]::IsOutputRedirected) {
    Set-PSReadLineOption -PredictionSource History
    Set-PSReadLineOption -PredictionViewStyle ListView
}

# Keys
Set-PSReadLineKeyHandler -Key UpArrow    -Function HistorySearchBackward
Set-PSReadLineKeyHandler -Key DownArrow  -Function HistorySearchForward
Set-PSReadLineKeyHandler -Key Tab        -Function MenuComplete
Set-PSReadLineKeyHandler -Key RightArrow -Function ForwardWord
Set-PSReadLineKeyHandler -Key Ctrl+z     -Function Undo

# --- Syntax highlight colours (Claude Ember) ---
Set-PSReadLineOption -Colors @{
    Command                = "#FF7A1A"
    Parameter              = "#FFA55C"
    String                 = "#8ED69B"
    Number                 = "#FFC53D"
    Operator               = "#FF5A36"
    Variable               = "#F8F4EE"
    Comment                = "#9E948A"
    InlinePrediction       = "#3B352F"
    ListPrediction         = "#FF7A1A"
    ListPredictionSelected = "#25221F"
}

# --- Prompt: folder, git branch (read from .git/HEAD, no git process), arrow that shows the last result ---
function prompt {
    $ok   = $?
    $esc  = [char]27
    $path = $PWD.Path
    if ($path.StartsWith($HOME, [StringComparison]::OrdinalIgnoreCase)) { $path = '~' + $path.Substring($HOME.Length) }

    # branch: walk up to the nearest .git and read HEAD (cheap, and nothing in the repo can run)
    $branch = ''
    try {
        $dir = $PWD.Path
        for ($i = 0; $i -lt 40 -and $dir; $i++) {
            $dotGit = Join-Path $dir '.git'
            if ([IO.Directory]::Exists($dotGit)) { $head = [IO.File]::ReadAllText((Join-Path $dotGit 'HEAD')); break }
            if ([IO.File]::Exists($dotGit)) {
                $m = [regex]::Match([IO.File]::ReadAllText($dotGit), 'gitdir:\s*(.+)')
                if ($m.Success) { $head = [IO.File]::ReadAllText((Join-Path (Join-Path $dir $m.Groups[1].Value.Trim()) 'HEAD')) }
                break
            }
            $dir = [IO.Path]::GetDirectoryName($dir)
        }
        if ($head -match 'ref:\s*refs/heads/(.+)') { $branch = $Matches[1].Trim() }
    } catch { }

    $violet = "$esc[38;2;230;216;195m"
    $pink   = "$esc[38;2;255;90;54m"
    $faint  = "$esc[38;2;158;148;138m"
    $arrow  = if ($ok) { "$esc[38;2;255;122;26m" } else { "$esc[38;2;255;77;77m" }
    $reset  = "$esc[0m"
    $git    = if ($branch) { " $faint`u{2387} $pink$branch" } else { '' }
    "`n$violet $path$git $arrow`u{276F}$reset "
}

# ============================================================
#  Pretty ls: Nerd Font icons, colour by type, folders first.
#  Needs the JetBrainsMono NFM font. (gci / dir still give raw objects.)
# ============================================================
# Built-in `ls` is an ALIAS (aliases outrank functions), so drop it.
Remove-Item Alias:ls -Force -ErrorAction SilentlyContinue

function ls {
    param([string]$Path = '.')

    $items = Get-ChildItem -LiteralPath $Path -Force -ErrorAction SilentlyContinue |
             Sort-Object @{ Expression = { -not $_.PSIsContainer } }, Name
    if (-not $items) { return }

    $esc = [char]27
    $reset = "$esc[0m"

    $cells = foreach ($i in $items) {
        if ($i.PSIsContainer) {
            $icon = "`u{f07b}"; $rgb = '255;122;26'                                   # folder
        } else {
            switch -Regex ($i.Extension.ToLower()) {
                '\.(ps1|psm1|psd1|sh|bat|cmd)$'                                         { $icon="`u{f1c9}"; $rgb='255;197;61'; break }   # script
                '\.(py|js|mjs|ts|jsx|tsx|c|cpp|h|cs|go|rs|java|rb|php|lua|html|css)$'   { $icon="`u{f1c9}"; $rgb='255;165;92'; break } # code
                '\.(json|ya?ml|toml|xml|ini|cfg|conf|env)$'                             { $icon="`u{f1c9}"; $rgb='255;201;153'; break }    # config
                '\.(md|markdown|rst|txt|log|nfo)$'                                      { $icon="`u{f15c}"; $rgb='191;181;170'; break } # text
                '\.(pdf|docx?|odt|rtf)$'                                                { $icon="`u{f1c1}"; $rgb='255;77;77'; break }     # docs
                '\.(xlsx?|csv|ods)$'                                                    { $icon="`u{f1c3}"; $rgb='142;214;155'; break }    # sheets
                '\.(pptx?|odp)$'                                                        { $icon="`u{f1c4}"; $rgb='255;122;26'; break }   # slides
                '\.(png|jpe?g|gif|bmp|webp|svg|ico|tiff?)$'                             { $icon="`u{f1c5}"; $rgb='230;216;195'; break }  # images
                '\.(mp4|mkv|avi|mov|webm|flv|wmv)$'                                     { $icon="`u{f1c8}"; $rgb='255;90;54'; break }    # video
                '\.(mp3|wav|flac|ogg|m4a|aac)$'                                         { $icon="`u{f1c7}"; $rgb='255;246;232'; break }    # audio
                '\.(zip|rar|7z|tar|gz|xz|bz2)$'                                         { $icon="`u{f1c6}"; $rgb='190;146;43';  break } # archives
                '\.(exe|msi|com|appx)$'                                                 { $icon="`u{f013}"; $rgb='255;77;77'; break }     # executables
                default                                                                  { $icon="`u{f15b}"; $rgb='191;181;170' }     # other
            }
        }
        [pscustomobject]@{ Icon = $icon; Name = $i.Name; Rgb = $rgb; Vis = $i.Name.Length + 2 }
    }

    $colW  = (($cells.Vis | Measure-Object -Maximum).Maximum) + 2
    $width = $Host.UI.RawUI.WindowSize.Width; if (-not $width -or $width -lt 20) { $width = 120 }
    $cols  = [Math]::Max(1, [Math]::Floor($width / $colW))
    $rows  = [Math]::Ceiling($cells.Count / $cols)

    for ($r = 0; $r -lt $rows; $r++) {
        $line = ''
        for ($c = 0; $c -lt $cols; $c++) {
            $idx = $r + $c * $rows
            if ($idx -ge $cells.Count) { continue }
            $x   = $cells[$idx]
            $pad = ' ' * ($colW - $x.Vis)
            $line += "$esc[38;2;$($x.Rgb)m$($x.Icon) $($x.Name)$reset$pad"
        }
        Write-Host $line
    }
}
